head.script:
scwin.onpageload = function() {
	cal.disableDate("20230829, 20230830");
    cal2.disableDate("20230829, 20230830");
};

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#cal2_input', 'key-sequence', {
			sequence: '20230829'
		});
	}
	scwin.setSimulate2 = function() {
		scwin.simulateWrapper('#cal_input', 'key-sequence', {
			sequence: '20230829'
		});
	}	
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('mf_cal2_calendar_selectbox_year_label').innerText != '2023년';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cal2_input').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cal2_input').focus()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cal_input').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cal2_img').click()");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
